func loadConfigFromFetch(configID string) templ.ComponentScript {
	return templ.ComponentScript{
		Name: `__templ_loadConfigFromFetch_f514`,
		Function: `function __templ_loadConfigFromFetch_f514(configID){var name;
	fetch('/config/'+configID)
	.then(response => {
	    if (!response.ok) {
	        throw new Error(` + "`" + `HTTP error! status: ${response.status}` + "`" + `);
	    }
	    return response.json();
	})
	.then(config => {
	    configName = config.name;
		document.getElementById("name").value = config.name
	    baseUrl = config.data.base_url;
	    configs = convertStructureToConfigs(config.data.structure);
	    renderConfigs();
	    hasChanged = false;
	    showToast("Config Loaded succesfully", 10000, "success");
	})
	.catch(error => {
	    console.error("Could not fetch the configuration:", error);
	    showToast("Failed to load the configuration. Please try again.", 10000, "error");
	});

	fetch('/config/version/'+configID)
	.then(response => {
	    if (!response.ok) {
	        throw new Error(` + "`" + `HTTP error! status: ${response.status}` + "`" + `);
	    }
	    return response.json();
	})
	.then(config => {
	    document.getElementById("version-display").innerHTML = "Version : "+config.full_version
	    version = config.full_version
	})
	.catch(error => {
	    console.error("Could not fetch the configuration:", error);
	    showToast("Failed to load the configuration. Please try again.", 10000, "error");
	});

	const modal = document.getElementById('databaseModal');

    modal.classList.add('opacity-0');
    setTimeout(() => {
        modal.classList.add('hidden');
    }, 300);
}`,
		Call:       templ.SafeScript(`__templ_loadConfigFromFetch_f514`, configID),
		CallInline: templ.SafeScriptInline(`__templ_loadConfigFromFetch_f514`, configID),
	}
}

